      endTexts:{survived:"🌟 <b>新航路とルネサンスの灯が、世界を一つにつなぎ始めた！（IFルート達成）</b>",completed:"🏁 200年を完走！ 印刷・芸術・宗教改革・大航海——中世から近代へ、世界が大きく動いた時代を見届けた。"},
      castles:[[0,"⚓","ジェノヴァの港"],[200,"🏰","ポルトガルの船宿"],[500,"👑","スペイン宮廷"],[900,"🌅","サンサルバドル島"],[1500,"🌍","新しい世界地図"]],
